"""Ampliação editorial das famílias; critérios práticos e fontes de âmbito explícito."""

def completar(produtos, fontes, *, guia, variante, componente, zona, tecnica, faq):
    def referencia(titulo, entidade, url, ambito):
        return dict(titulo=titulo, entidade=entidade, url=url,
                    data_consulta='2026-10-21', ambito=ambito)

    fontes.update({
        'prodalimentos': referencia('Materiais em contacto com alimentos', 'Comissão Europeia',
            'https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials_en',
            'Recipientes, utensílios e embalagens destinados a contacto alimentar. Enquadramento geral; não comprova a conformidade de qualquer artigo ilustrado.'),
        'prodprotecao': referencia('Equipamento de proteção individual', 'Comissão Europeia',
            'https://single-market-economy.ec.europa.eu/sectors/mechanical-engineering/personal-protective-equipment-ppe_en',
            'Distingue equipamento destinado a proteger de riscos e o seu enquadramento. Não certifica os produtos ou fotografias desta biblioteca.'),
        'prodcaixas': referencia('Sistemas construtivos de caixas de cartão', 'FEFCO',
            'https://www.fefco.org/technical-information/fefco-code',
            'Classificação de construções de embalagem de cartão. Identificar uma forma não demonstra resistência, proteção ou reciclabilidade.'),
        'prodvelas': referencia('Segurança na utilização de velas', 'Governo do Reino Unido',
            'https://www.gov.uk/government/publications/fire-safety-when-celebrating/fire-safety-when-celebrating-accessible',
            'Orientação doméstica sobre chama e materiais inflamáveis; não é um ensaio nem instruções de uma vela específica.'),
        'prodacessos': referencia('Informação aos titulares em sistemas de acesso por cartão', 'CNIL',
            'https://cnil.fr/fr/RGPD-exemple-information-acces-aux-locaux-professionnels-par-badge',
            'Exemplo institucional de informação sobre tratamento de dados num sistema de acesso. Não demonstra capacidade eletrónica de um cartão ou crachá.'),
    })
    por_id = {g['id']: g for g in produtos}
    def ampliar(id, tipos, criterios, relacionados=()):
        g = por_id[id]
        g['tipos'].extend(tipos)
        g['criterios_escolha'].extend(criterios)
        g['relacionados'] = list(dict.fromkeys(g['relacionados'] + list(relacionados)))
        g['data_revisao'] = '2026-10-21'

    ampliar('canetas-e-escrita', [
        variante('Marcadores e sublinhadores', 'Uma ponta fina para anotar e uma ponta biselada para destacar texto resolvem tarefas diferentes. Experimente a tinta no papel ou na superfície prevista, observando transparência no verso e secagem.', 'Formato da ponta, tampa, largura do traço e superfície de escrita indicada.', 'Leitura, estudo, apresentação e marcação temporária conforme o instrumento.'),
    ], ['Escolha primeiro a tarefa: texto contínuo, apontamentos rápidos, desenho ou destaque. Só depois avalie mecanismo, pega e apresentação.',
        'No lápis, experimente a dureza no papel habitual; na lapiseira, verifique diâmetro e forma de carregar a mina. O corpo semelhante não torna os consumíveis equivalentes.'], ['embalagem-e-apresentacao'])
    por_id['canetas-e-escrita']['resumo'] = 'Da esferográfica ao marcador: conheça diferenças de traço, mecanismo, consumíveis e personalização dos instrumentos de escrita.'
    ampliar('artigos-de-escritorio', [
        variante('Calendários de mesa e de parede', 'O calendário mostra uma sequência de datas; a agenda acrescenta espaço de registo. Um modelo de mesa precisa de apoio estável, enquanto um de parede exige observar fixação e leitura à distância.', 'Período abrangido, tamanho dos números, mudança de folha e espaço para notas.', 'Planeamento partilhado, receção ou secretária.'),
        variante('Organização de secretária', 'Porta-canetas, tabuleiros e pequenos organizadores separam objetos por frequência de uso. Verifique se o acesso continua fácil com o conjunto completo e se a base cabe na secretária.', 'Profundidade, estabilidade, divisórias e facilidade de retirar o conteúdo.', 'Postos de trabalho, espaços de atendimento e estudo.'),
    ], ['Num caderno para notas rápidas, teste a abertura com uma mão; para consulta frequente, observe como se encontra uma página já preenchida.',
        'Uma agenda datada pode deixar de ser útil antes de terminar o papel. Distinga organização por dia, semana e mês de um bloco sem datas.'], ['embalagem-e-apresentacao'])
    ampliar('tecnologia', [
        variante('Cabos de ligação', 'O encaixe físico é apenas o primeiro passo. Separe o conector de cada ponta, o transporte de energia, a transferência de dados e uma eventual saída de imagem. O formato USB-C não identifica por si só estas funções. [produsb]', 'Comprimento útil, pontas, função documentada e espaço junto às portas.', 'Ligação entre os equipamentos efetivamente utilizados.'),
        variante('Acessórios para computador e telemóvel', 'Tapetes, capas e bolsas organizam ou acompanham o equipamento; adaptadores e concentradores acrescentam ligações quando suportadas. Não trate um acessório passivo como um dispositivo eletrónico.', 'Medidas, recortes, ventilação, acesso a comandos e portas necessárias.', 'Secretária, trabalho móvel e arrumação.'),
    ], ['Para áudio, ensaie os comandos, a captação de voz se existir microfone e o método de ligação no ambiente previsto. Uma função de reprodução não implica função de chamada.',
        'Registe a combinação completa para carregamento: dispositivo, fonte de alimentação, cabo e função pretendida. Uma porta visualmente igual pode ter capacidades diferentes. [produsb]'], ['mobilidade-ferramentas-e-seguranca'])
    ampliar('garrafas-copos-e-canecas', [
        variante('Recipientes térmicos e copos de viagem', 'Distinga o recipiente destinado a beber em movimento do destinado a guardar a bebida até ao serviço. Observe bocal, acionamento da tampa e possibilidade de o transportar fechado; a descrição térmica não indica um número de horas.', 'Acesso ao bocal, desmontagem das juntas e condições documentadas de transporte.', 'Percursos diários, pausas e deslocações.'),
        variante('Garrafas para atividade desportiva', 'Um bocal de acionamento rápido e um gargalo largo oferecem experiências de uso distintas. Teste a pega e a abertura sem deduzir estanquidade pelo aspeto da tampa.', 'Forma de agarrar, bocal, limpeza e encaixe no suporte previsto.', 'Atividade física e uso em deslocação.'),
        variante('Lancheiras e caixas de refeição', 'Uma caixa rígida organiza o alimento; uma bolsa exterior transporta essa caixa. Identifique divisórias, peças removíveis e fechos. Contacto alimentar e modo de aquecimento dependem das instruções do artigo. [prodalimentos]', 'Dimensões internas, encaixe da refeição, separação de alimentos e acesso para lavar.', 'Refeições fora de casa e pausas no trabalho.'),
        variante('Utensílios de cozinha e acessórios de bar', 'Talheres, espátulas, tábuas, abre-garrafas e saca-rolhas devem ser escolhidos pela tarefa e pela pega. Um conjunto pode reunir peças com materiais e cuidados diferentes.', 'Acesso para limpar, arrumação, bordos e partes que tocam em alimentos.', 'Preparação, serviço e utilização à mesa.'),
    ], ['Separe contacto alimentar, transporte e aquecimento: a aptidão para um destes usos não demonstra a aptidão para os outros. A referência institucional abrange recipientes e utensílios, sem validar um artigo concreto. [prodalimentos]'], ['casa-decoracao-e-cuidados-pessoais','desporto-lazer-e-exterior'])
    por_id['garrafas-copos-e-canecas']['fontes'].append('prodalimentos')
    por_id['garrafas-copos-e-canecas']['resumo'] = 'Garrafas, copos, canecas, recipientes térmicos, lancheiras e utensílios: distinga consumo, transporte, preparação e limpeza.'
    ampliar('sacos-e-mochilas', [
        variante('Sacos dobráveis', 'A forma de dobrar e guardar condiciona o espaço ocupado entre utilizações. Uma bolsa integrada, um fecho ou uma tira de retenção oferecem formas diferentes de arrumação.', 'Sequência de dobra, volume guardado e facilidade de voltar a abrir.', 'Compras e transporte ocasional.'),
        variante('Sacos térmicos e bolsas de refeição', 'Distinga o espaço para recipientes do revestimento interior e de eventuais elementos de frio. Uma aparência almofadada ou metalizada não demonstra desempenho térmico nem adequação a contacto direto com alimentos.', 'Medidas úteis, abertura, limpeza do interior e condições de utilização indicadas.', 'Transporte de refeições segundo as instruções dos recipientes e da bolsa.'),
        variante('Sacos de desporto e bolsas para computador', 'Uma abertura ampla facilita retirar peças volumosas; uma bolsa de equipamento privilegia encaixe e acesso aos compartimentos. Verifique se separar calçado, roupa ou acessórios exige divisórias próprias.', 'Dimensões internas, fechos, alça e distribuição do conteúdo.', 'Treino, deslocações diárias e transporte de equipamento.'),
        variante('Malas e acessórios de viagem', 'Uma mala com rodas, uma bolsa de higiene e um identificador de bagagem têm funções distintas. Organize o percurso de uso: transportar, abrir, encontrar e voltar a guardar.', 'Pegas, rodas se existirem, divisórias, fecho e medidas relevantes para o percurso.', 'Viagens e estadias; requisitos de transporte devem ser confirmados para a viagem concreta.'),
    ], ['Capacidade nominal e encaixe útil respondem a perguntas diferentes: use as dimensões do conteúdo e simule a abertura com os compartimentos ocupados.',
        'Coloque o saco na posição habitual de uso e retire um objeto do fundo. Este ensaio simples revela acessos incómodos que uma fotografia não mostra.'], ['desporto-lazer-e-exterior','embalagem-e-apresentacao'])
    ampliar('texteis', [
        variante('Roupa de trabalho e de desporto', 'Uma peça de identificação de equipa e uma peça destinada a uma tarefa física podem exigir cortes e movimentos diferentes. Faça a prova com os gestos e as camadas de roupa previstos; roupa de trabalho não equivale automaticamente a equipamento de proteção.', 'Liberdade de movimentos, bolsos, fechos e posição da mensagem durante a atividade.', 'Equipas, tarefas profissionais e prática recreativa.'),
        variante('Chapéus, cachecóis e outros acessórios', 'A forma de vestir e ajustar pode deixar a área personalizada dobrada ou parcialmente escondida. Observe o artigo colocado, em vez de medir apenas a peça estendida.', 'Ajuste, costuras, contacto com a pele e leitura na posição de uso.', 'Complemento de vestuário e identificação de grupos.'),
    ], ['Composição identifica fibras; construção descreve como se organiza o tecido; corte define a forma da peça. Registe estes três aspetos separadamente.',
        'Os cuidados indicados na etiqueta abrangem tratamentos distintos. Uma temperatura de passagem a ferro não deve ser deduzida apenas da fibra. [prodcare]'], ['desporto-lazer-e-exterior','mobilidade-ferramentas-e-seguranca'])

    produtos.extend([
        guia('casa-decoracao-e-cuidados-pessoais','casa','Casa, decoração e cuidados pessoais',
          'Objetos para organizar, decorar, preparar tarefas domésticas e acompanhar rotinas de cuidado pessoal: escolha pela função e pelo local de utilização.',
          ['casa','decoração','manta','vela','organizador','espelho','escova','necessaire','higiene','cuidados pessoais'],
          [variante('Organização e decoração', 'Caixas de arrumação, pequenos organizadores e objetos decorativos diferem na relação com o espaço. Uma peça exposta precisa de ser legível e estável no local previsto; uma peça de arrumação deve permitir encontrar e retirar o conteúdo.', 'Base, dimensões, abertura e espaço ocupado com o conteúdo.', 'Secretária, quarto, receção ou outras zonas interiores.'),
           variante('Têxteis para casa', 'Mantas, toalhas e acessórios têxteis são escolhidos pela dimensão em uso e pela forma de guardar. Uma manta dobrada pode mostrar uma zona diferente da que fica visível quando estendida.', 'Medidas abertas, volume guardado, textura e etiqueta de cuidados.', 'Acolhimento, descanso e utilização doméstica.'),
           variante('Cozinha e pequenas tarefas', 'Pegas, panos e acessórios de preparação não devem ser confundidos com recipientes de refeição. No caso de uma pega destinada a contacto com calor, a aparência acolchoada não demonstra proteção térmica.', 'Pega, área de utilização, limpeza e instruções específicas.', 'Preparação e arrumação; veja também o guia de bebidas e refeições.'),
           variante('Velas e elementos decorativos com chama', 'Distinga uma vela destinada a arder de um objeto apenas decorativo. O local de colocação faz parte da escolha: deve ser possível afastar materiais inflamáveis. [prodvelas]', 'Base, instruções de uso e distância a objetos próximos.', 'Ambientes interiores onde seja possível cumprir as condições de utilização.'),
           variante('Acessórios de cuidado pessoal', 'Espelhos, escovas, pentes e bolsas de higiene acompanham rotinas diferentes. Observe se a pessoa precisa de ver, agarrar, abrir ou limpar o objeto com uma mão. Um acessório não deve ser apresentado como tratamento de saúde.', 'Abertura, pega, bordos, arrumação e limpeza das partes de contacto.', 'Uso pessoal, viagens e organização de pequenos objetos.')],
          ['Escolha uma tarefa concreta e o local onde o objeto ficará. Um organizador para uso diário e um objeto decorativo exigem critérios diferentes.', 'Em conjuntos, identifique cada peça: a bolsa não descreve o material, os cuidados ou a função do seu conteúdo.'],
          [componente('Tecidos e enchimentos',['fibras têxteis'],'materiais-texteis','Identifique exterior, forro e eventual enchimento separadamente.'), componente('Partes rígidas e pegas',['plásticos'],'plasticos','Observe uniões, peças desmontáveis e acabamento nas zonas de contacto.'), componente('Bases e recipientes decorativos',['vidro','cerâmica'],'vidro-e-ceramica','Estabilidade e integridade devem ser observadas no objeto completo, não deduzidas do material.')],
          [zona('Face exterior ou painel têxtil','Escolha uma zona visível durante a utilização e acessível sem desmontagem indevida.'), zona('Bolsa ou embalagem','A personalização exterior não deve ocultar instruções nem dificultar abertura.')],
          [tecnica('serigrafia','Pode ser avaliada em painéis têxteis ou superfícies acessíveis, conforme tinta, acabamento e cuidados.'), tecnica('bordado','Avalie espessura, acesso ao verso e posição de uso; uma manta com enchimento exige análise da construção.'), tecnica('tampografia','Avalie objetos rígidos pela curvatura, suporte e aderência, mantendo livres as zonas de contacto relevantes.')],
          ['Meça a peça aberta e guardada; a fotografia pode mostrar apenas uma destas posições.', 'Teste acesso e limpeza com o objeto no local previsto. Uma superfície decorativa recortada pode tornar a manutenção menos prática.', 'Para contacto com alimentos, procure instruções próprias para esse uso. A Comissão Europeia inclui utensílios e louça no âmbito dos materiais de contacto alimentar. [prodalimentos]'],
          ['Não atribua proteção térmica a uma pega ou luva de cozinha com base na fotografia.', 'Um acessório de cuidado pessoal não demonstra efeitos de saúde, higiene ou bem-estar por integrar esta família.'],
          ['Siga a etiqueta de cuidados de mantas e outros têxteis; tratamentos de lavagem e secagem devem ser identificados na peça. [prodcare]', 'Apague velas quando não houver vigilância e mantenha-as afastadas de materiais inflamáveis. [prodvelas]'],
          ['Que tarefa e espaço vai servir?','Como se abre e limpa?','Que parte fica visível em uso?'],
          [faq('Uma manta e a sua bolsa têm os mesmos cuidados?','Não necessariamente. Identifique os materiais e as instruções de cada parte.'), faq('Uma pega acolchoada protege de qualquer temperatura?','A fotografia e a espessura aparente não demonstram esse desempenho. Procure as instruções e os limites do artigo.'), faq('A decoração pode ser aplicada numa zona de contacto alimentar?','A zona e o processo precisam de avaliação específica para a utilização prevista; não generalize a adequação da face exterior ao interior.')],
          ['prodvelas','prodcare','prodalimentos'], ['garrafas-copos-e-canecas','texteis','embalagem-e-apresentacao','como-escolher-o-material']),

        guia('desporto-lazer-e-exterior','desporto','Desporto, lazer e exterior',
          'Da atividade recreativa ao piquenique: distinga objetos para transportar, jogar, sentar e acompanhar o tempo passado no exterior.',
          ['desporto','praia','piquenique','campismo','cadeira dobrável','jogos','lazer','exterior'],
          [variante('Atividade física e transporte', 'Sacos de desporto, toalhas e recipientes de bebida acompanham a atividade, mas não desempenham a mesma função. Comece pelo conteúdo a transportar e pelos momentos de uso antes e depois do exercício.', 'Acesso, compartimentos, forma de transportar e separação de objetos.', 'Treino recreativo e atividades de grupos.'),
           variante('Praia e piquenique', 'Toalhas, mantas, bolsas e conjuntos de refeição podem formar uma seleção coerente se houver espaço para os guardar e limpar. Identifique o que fica no chão, o que toca em alimentos e o que apenas transporta.', 'Dimensões abertas, arrumação depois de usar e peças laváveis.', 'Pausas ao ar livre e convívios.'),
           variante('Cadeiras e acessórios de campismo', 'Uma cadeira dobrável alterna entre uma posição de transporte e uma posição de uso. Observe a sequência de abertura, os pontos de apoio e a forma de guardar; o tamanho da bolsa não descreve o assento aberto.', 'Dimensões abertas e fechadas, estabilidade no piso previsto e carga documentada.', 'Permanência em espaços exteriores adequados às instruções do artigo.'),
           variante('Jogos e atividades recreativas', 'Jogos de mesa portáteis, bolas e pequenos acessórios requerem regras de uso e arrumação diferentes. Conte as peças e avalie como se conservam juntas depois da atividade.', 'Espaço necessário, peças pequenas, idade indicada e facilidade de guardar.', 'Convívio, pausas e participação em grupo.')],
          ['Planeie uma sequência completa: levar, abrir, utilizar, limpar e guardar. Um artigo útil no destino pode ser pouco prático durante o percurso.', 'Em atividades organizadas, distinga materiais de participação dos que a equipa precisa para trabalhar.'],
          [componente('Painéis, assentos e bolsas',['materiais têxteis'],'materiais-texteis','Identifique a construção e o cuidado de cada peça; uma bolsa não descreve o assento.'), componente('Estruturas, uniões e ferragens',['metais'],'metais','Observe articulações, pontos de apoio e instruções de montagem.'), componente('Apoios e peças moldadas',['plásticos'],'plasticos','Identifique zonas móveis, encaixes e eventuais peças de substituição.')],
          [zona('Painel de saco ou tecido','Escolha uma área acessível e visível na posição real de utilização.'), zona('Bolsa de transporte','A mensagem pode ficar guardada durante o uso; decida se esse é o efeito pretendido.')],
          [tecnica('serigrafia','Avalie tinta, acabamento e flexão do painel; o uso no exterior não é uma garantia de resistência da impressão.'), tecnica('transfers','Verifique a modalidade e a compatibilidade com calor e pressão, sem atingir estruturas ou revestimentos sensíveis.')],
          ['Numa cadeira, observe a abertura completa e o contacto dos apoios com o piso previsto, seguindo as instruções.', 'Para um jogo, avalie tempo de preparação, número de peças e arrumação após a atividade.', 'Em sacos e bolsas, ensaie o percurso com o conteúdo habitual em vez de escolher apenas pela capacidade nominal.'],
          ['Um artigo recreativo não equivale a equipamento de proteção. A referência europeia distingue produtos usados ou segurados para proteger contra riscos. [prodprotecao]', 'Não deduza proteção solar, impermeabilidade ou resistência ao vento do nome da família ou da imagem.'],
          ['Antes de guardar, siga as instruções de limpeza e secagem de cada componente; não atribua o mesmo tratamento ao tecido e à estrutura.', 'Interrompa a utilização se uma articulação não abrir ou fechar como previsto e consulte as instruções em vez de forçar o mecanismo.'],
          ['Quanto espaço ocupa aberto e fechado?','Que piso e percurso estão previstos?','Que carga ou condições de uso estão documentadas?'],
          [faq('Uma cadeira para exterior pode ficar sempre à chuva?','A designação não confirma exposição permanente. Consulte condições de utilização e armazenamento.'), faq('Uma bolsa térmica mantém qualquer refeição segura?','O desempenho e as condições de transporte precisam de documentação; a bolsa não substitui as instruções de conservação do alimento.'), faq('Um acessório desportivo é equipamento de proteção?','Só a finalidade e a documentação aplicáveis permitem avaliar essa função, não a associação ao desporto. [prodprotecao]')],
          ['prodprotecao'], ['sacos-e-mochilas','garrafas-copos-e-canecas','texteis','clubes-desportivos']),

        guia('eventos-identificacao-e-premios','eventos','Eventos, identificação e prémios',
          'Fitas, cartões, pulseiras, pins e distinções apoiam identificação, participação e reconhecimento. Separe o objeto físico do sistema em que será usado.',
          ['evento','identificação','crachá','fita','lanyard','cartão','pulseira','pin','troféu','medalha'],
          [variante('Fitas, crachás e cartões', 'A fita suspende; o porta-cartões contém; o cartão apresenta a informação. Defina o conjunto pela orientação, pelo ponto de fixação e pela facilidade de ler o nome sem rodar o suporte.', 'Formato útil, abertura, orientação horizontal ou vertical e fixação.', 'Receção, sessões e identificação de equipas.'),
           variante('Pulseiras de participação', 'Uma pulseira pode distinguir grupos por cor ou informação impressa. Isso não demonstra que impeça transferência entre pessoas, que seja inviolável ou que comunique com um leitor.', 'Fecho, ajuste, legibilidade e processo de verificação utilizado.', 'Participação em atividades e organização de grupos.'),
           variante('Pins e crachás tipo botão', 'Um pin ou botão prende-se ao vestuário e pode transmitir uma mensagem curta. A área pequena favorece desenhos simples; o sistema de fixação condiciona colocação e remoção.', 'Ponta, fecho, verso e leitura à dimensão final.', 'Identificação visual e expressão de participação.'),
           variante('Troféus e medalhas', 'O troféu é normalmente apresentado com uma base ou apoio; a medalha pode ser suspensa numa fita ou guardada num estojo. Distinga uma mensagem comum do nome e da data individuais.', 'Base, arestas, espaço de inscrição, suspensão e embalagem.', 'Reconhecimento, participação e cerimónias.')],
          ['Separe participante, equipa e distinção: cada papel pode precisar de informação e formato próprios.', 'Para uma entrega individual, organize nome, texto e sequência de distribuição antes de preparar as inscrições.'],
          [componente('Fitas e cordões',['materiais têxteis'],'materiais-texteis','Observe largura, costura e forma de união aos acessórios.'), componente('Cartões e suportes flexíveis',['papel','cartão'],'papel-e-cartao','Confirme dimensão, espessura e leitura dentro do porta-cartões.'), componente('Medalhas e ferragens',['metais'],'metais','Identifique acabamento e partes móveis; aparência dourada não identifica a liga.'), componente('Placas e troféus transparentes',['vidro','outros materiais transparentes'],'vidro-e-ceramica','A fotografia não distingue vidro de outros materiais transparentes; consulte a composição.')],
          [zona('Frente de cartão ou crachá','Hierarquize nome, função e informação essencial, sem cobrir furos ou fixações.'), zona('Face de medalha ou troféu','Meça o espaço efetivo e reveja acentos, nomes e data antes de produzir.')],
          [tecnica('impressao-uv','Avalie superfície e fixação de placas e cartões, preservando a função das zonas de leitura.'), tecnica('gravacao-a-laser','Avalie a composição e o revestimento, bem como contraste e dimensão dos caracteres.'), tecnica('crachas-automaticos','Este guia trata a montagem de crachás tipo pin/botão; não descreve todos os cartões e sistemas de identificação.')],
          ['Leia uma amostra à distância prevista e com a fita colocada; o texto pode parecer suficiente apenas quando está pousado.', 'Distinga impressão fixa de informação individual. Nomes longos e funções extensas devem caber no mesmo esquema.', 'Se existir controlo eletrónico, documente separadamente cartão, leitor e sistema. A imagem de um crachá não demonstra essa função.'],
          ['Uma cor ou impressão não garante autenticidade nem controlo de acesso.', 'Num sistema que trate dados pessoais, a informação às pessoas faz parte do processo. A referência da CNIL apresenta um exemplo de informação para acesso por cartão. [prodacessos]'],
          ['Verifique fechos e pontas antes da distribuição, de acordo com as instruções do conjunto.', 'Guarde troféus e medalhas com separação entre peças quando o contacto puder marcar as superfícies; teste a apresentação com o conjunto real.'],
          ['Que informação tem de ser lida?','Há nomes individuais?','O objeto identifica ou integra um sistema de acesso?'],
          [faq('Uma pulseira prova que uma pessoa tem autorização?','O objeto só tem esse papel dentro do processo de validação definido pela organização; não o garante por si só.'), faq('Qualquer fita serve para qualquer porta-cartões?','Verifique o encaixe, a orientação e o comportamento do conjunto colocado.'), faq('É possível gravar qualquer troféu transparente?','Não presuma composição ou resposta à gravação pela transparência; avalie o material e uma amostra.')],
          ['prodacessos'], ['eventos','crachas-automaticos','embalagem-e-apresentacao','como-preparar-um-logotipo']),

        guia('mobilidade-ferramentas-e-seguranca','mobilidade','Mobilidade, ferramentas e segurança',
          'Acessórios de deslocação, lanternas, pequenas ferramentas e artigos de visibilidade têm funções distintas. Escolha pela tarefa e pela documentação do objeto concreto.',
          ['automóvel','bicicleta','lanterna','ferramenta','multifunções','fita métrica','refletor','colete','mobilidade','segurança'],
          [variante('Acessórios para automóvel e bicicleta', 'Suportes, organizadores, bolsas e pequenos acessórios devem ser avaliados no ponto de instalação. Um encaixe que funciona num local pode interferir com comandos ou com a utilização noutro.', 'Fixação, dimensões, acesso e possibilidade de remover sem dificultar a utilização.', 'Arrumação e apoio à deslocação no equipamento compatível.'),
           variante('Lanternas', 'Uma luz de mão, uma luz de apoio e uma luz para montar num veículo não têm necessariamente a mesma finalidade. Observe como se aciona o interruptor e como se troca ou recarrega a alimentação.', 'Formato do feixe, apoio, alimentação e instruções de uso.', 'Iluminação de proximidade e tarefas previstas para o artigo.'),
           variante('Ferramentas pequenas e multifunções', 'Uma ferramenta individual privilegia uma operação; um conjunto dobrável reúne peças que se abrem de formas diferentes. Conte as funções úteis para a tarefa e observe o acesso a cada peça, sem assumir aptidão profissional.', 'Pega, abertura, bloqueios quando existam e instruções para cada operação.', 'Pequenas tarefas compatíveis com o objeto e com as competências de quem o utiliza.'),
           variante('Fitas métricas', 'Observe a escala, a extremidade de apoio, a forma de recolher e o acesso ao travão se existir. Uma graduação impressa não demonstra precisão ou aptidão para uma medição regulamentada.', 'Legibilidade, unidades, comprimento útil e recolha controlada.', 'Medições adequadas à documentação do instrumento.'),
           variante('Artigos refletores e de proteção', 'Distinga um acessório com uma zona refletora de um equipamento destinado a proteger de um risco. Óculos ou coletes fotografados não permitem identificar nível de proteção ou conformidade. [prodprotecao]', 'Finalidade, instruções, tamanho e documentação aplicável ao artigo.', 'Utilizações expressamente previstas na documentação, sem extrapolar pela aparência.')],
          ['Defina uma tarefa e o local de utilização antes de escolher o número de funções.', 'Se o objeto tiver uma função de proteção, separe essa avaliação da escolha da mensagem ou da embalagem.'],
          [componente('Peças de trabalho, lâminas e articulações',['metais'],'metais','Identifique cada peça e respetivo uso; uma carcaça metálica não descreve todas as ferramentas.'), componente('Pegas, invólucros e apoios',['plásticos'],'plasticos','Observe textura, encaixes e espaço disponível para agarrar.'), componente('Bolsas e painéis vestíveis',['materiais têxteis'],'materiais-texteis','Não deduza a composição ou função de faixas pela cor e brilho.')],
          [zona('Invólucro ou pega livre','Mantenha legíveis escalas, instruções e informação técnica; não cubra zonas de preensão necessárias.'), zona('Bolsa de transporte','Pode receber a mensagem sem intervir no mecanismo, desde que o processo seja adequado ao material.')],
          [tecnica('gravacao-a-laser','Avalie revestimento e zona de aplicação sem atingir arestas de trabalho, mecanismos ou informação técnica.'), tecnica('tampografia','Avalie aderência e curvatura do invólucro, evitando botões e apoios.'), tecnica('transfers','Em peças vestíveis, confirme se a intervenção é permitida e onde pode ser feita; não cubra zonas funcionais ou refletoras.')],
          ['Experimente abrir e fechar cada peça com controlo. O número de funções não explica a facilidade de utilização.', 'Numa lanterna, verifique se os comandos podem ser usados na posição prevista e como se acede à alimentação.', 'Para proteção, procure finalidade e documentação aplicáveis. O enquadramento europeu de EPI é específico para produtos destinados a proteger de riscos. [prodprotecao]'],
          ['Não atribua homologação, precisão, resistência à água ou isolamento elétrico pelo nome do ficheiro ou aspeto.', 'Um acessório luminoso ou refletor não deve ser apresentado como substituto de equipamento exigido para uma utilização específica.'],
          ['Respeite as instruções de lâminas, articulações e alimentação; guarde as peças na posição indicada.', 'Observe danos e funcionamento antes de utilizar. Não use a personalização para ocultar marcações de segurança.'],
          ['Qual é a tarefa?','Como se abre e fixa?','Que função e limites estão documentados?'],
          [faq('Mais funções tornam uma ferramenta mais adequada?','Não necessariamente. Acesso, pega e utilidade de cada peça para a tarefa são critérios mais úteis.'), faq('Uma faixa brilhante demonstra proteção certificada?','Não. A imagem não permite avaliar documentação, finalidade nem desempenho.'), faq('Pode personalizar-se um equipamento de proteção?','É necessário confirmar se o procedimento e a zona são permitidos para esse equipamento e preservam as suas funções.')],
          ['prodprotecao'], ['tecnologia','metais','materiais-texteis','como-escolher-a-tecnica']),

        guia('embalagem-e-apresentacao','embalagem','Embalagem e apresentação',
          'Caixas, sacos, estojos, separadores e cartões organizam a entrega de um artigo ou conjunto. A escolha começa pelo encaixe e pela experiência de abrir.',
          ['embalagem','caixa','saco de apresentação','estojo','separador','cartão','acondicionamento','conjunto'],
          [variante('Sacos e bolsas de apresentação', 'Uma abertura simples facilita retirar o artigo; cordões, abas ou fechos alteram a forma de acesso. Observe se as pegas suportam o modo de transporte previsto e se o conteúdo fica exposto.', 'Boca, fundo, pegas e posição do objeto dentro do saco.', 'Entrega em mão e apresentação de conjuntos.'),
           variante('Caixas dobráveis e caixas rígidas', 'As dobras, abas e tampas definem a sequência de montagem e abertura. A classificação técnica de caixas de cartão descreve construções; não comprova por si só resistência ou proteção. [prodcaixas]', 'Medidas internas, fecho, montagem e forma de retirar o artigo.', 'Apresentação individual, conjuntos e organização da entrega.'),
           variante('Estojos', 'Um estojo pode acompanhar um artigo durante o uso ou servir apenas na entrega. Verifique o espaço livre junto a pegas, clips e tampas e a forma como o objeto é retirado.', 'Abertura, apoio interno, fecho e volume guardado.', 'Instrumentos de escrita, pequenos acessórios e conjuntos.'),
           variante('Separadores e elementos de encaixe', 'Uma divisória separa objetos; um encaixe procura mantê-los numa posição definida. Teste o conjunto real para perceber se uma peça roda, sai do lugar ou dificulta retirar outra.', 'Folgas, acesso dos dedos, orientação e montagem.', 'Conjuntos com vários componentes.'),
           variante('Cartões e informação de acompanhamento', 'Um cartão pode apresentar a mensagem ou indicar como começar a usar o objeto. Separe essa mensagem das instruções essenciais e confirme que estas continuam disponíveis depois de abrir.', 'Leitura, posição, idiomas necessários e relação com a abertura.', 'Acolhimento e apresentação informativa.')],
          ['Distinga entrega em mão de expedição. A embalagem de apresentação pode precisar de acondicionamento exterior para o percurso.', 'Monte um exemplar com todos os componentes e percorra a abertura como alguém que ainda não conhece o conjunto.'],
          [componente('Paredes e separadores',['papel','cartão'],'papel-e-cartao','Identifique espessura, construção e acabamento. Gramagem e rigidez são propriedades distintas. [prodboard]'), componente('Estojos e caixas com partes rígidas',['madeira','bambu'],'madeira-e-bambu','A aparência não identifica a espécie, a composição ou o tratamento; confirme o material.'), componente('Bolsas e fitas',['materiais têxteis'],'materiais-texteis','Observe costuras, cordões e forma de união às outras peças.')],
          [zona('Tampa ou face exterior','Observe a orientação antes e depois de abrir, evitando dobragens que atravessem informação essencial.'), zona('Cartão e separadores','Verifique se a mensagem fica visível ou escondida pelo artigo e se há espaço para retirar cada peça.')],
          [tecnica('impressao-uv','Avalie acabamento e aderência da face escolhida; a impressão não deve impedir dobras ou fechos.'), tecnica('serigrafia','Avalie a superfície, a tinta e a montagem, incluindo eventuais painéis têxteis.'), tecnica('gravacao-a-laser','Em suportes adequados, ensaie material, revestimento e efeito; a aparência de madeira não basta.')],
          ['Meça o artigo na posição embalada e com os acessórios. A medida exterior da caixa não é o espaço interior útil.', 'Abra, retire e volte a colocar cada componente; folgas pequenas podem bloquear o acesso e folgas grandes podem permitir movimento.', 'Se houver transporte, documente o percurso e os ensaios relevantes; uma construção visualmente robusta não demonstra proteção contra impacto.', 'Defina como se separam os componentes depois do uso, sem afirmar reciclabilidade apenas pela aparência.'],
          ['Apresentação cuidada não é garantia de qualidade do artigo nem de proteção durante o transporte.', 'Uma embalagem para contacto direto com alimentos requer avaliação para esse uso; a designação de caixa ou saco de oferta não o demonstra. [prodalimentos]'],
          ['Guarde os componentes segundo as instruções dos materiais e do artigo; não reutilize uma embalagem danificada para uma função que não foi avaliada.', 'Mantenha as instruções do objeto acessíveis depois de retirar a apresentação exterior.'],
          ['O conjunto cabe com todos os acessórios?','Como se retira cada peça?','A entrega é em mão ou envolve transporte?'],
          [faq('Uma caixa de apresentação serve para expedir?','Pode precisar de proteção exterior e de avaliação do percurso. A apresentação, por si só, não demonstra aptidão para expedição.'), faq('Mais gramagem significa mais proteção?','Não basta. Construção, encaixe e comportamento do conjunto também precisam de avaliação.'), faq('O que distingue apresentação de premium?','A apresentação é uma dimensão concreta de escolha. Premium continua a ser uma designação editorial transversal, sem garantia automática de qualidade.')],
          ['prodcaixas','prodboard','prodalimentos'], ['brindes-premium','papel-e-cartao','canetas-e-escrita','sacos-e-mochilas','montagem-e-acabamentos']),
    ])
    for g in produtos:
        if g['id'] not in por_id:
            g['data_revisao'] = '2026-10-21'
